			pSpace += 4 * (uintptr(nIdxCol))
			(*IndexSample)(unsafe.Pointer((*Index)(unsafe.Pointer(pIdx)).FaSample + uintptr(i)*20)).FanLt = pSpace
			pSpace += 4 * (uintptr(nIdxCol))
