//   flush:
//     AGGSTEP
//     while( 1 ){
//       if( (regStart--)<=0 ){
//         AGGINVERSE
//         if( eof ) break
//       }
//       RETURN_ROW
//     }
//     while( !eof csrCurrent ){
//       RETURN_ROW
//     }
